SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='66e9eef7-cf62-5a62-81bd-74fd9102e142'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('0bcce007-bdbc-5d6c-bbd8-9a692a952fb6','0b233dd1-0586-55e2-a08c-460cbbaaed4c')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='66e9eef7-cf62-5a62-81bd-74fd9102e142'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='66e9eef7-cf62-5a62-81bd-74fd9102e142'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('0bcce007-bdbc-5d6c-bbd8-9a692a952fb6','0b233dd1-0586-55e2-a08c-460cbbaaed4c')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='66e9eef7-cf62-5a62-81bd-74fd9102e142'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
 JOIN platform.runtime_command_receipt q ON q.id='0bcce007-bdbc-5d6c-bbd8-9a692a952fb6' AND q.owner_module_id='customer_buyer_profile' AND q.operation='SH-004.v1'
  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-shared-identical-text-key' AND q.fingerprint='fc74b43b2249294f3e78d89fb97f37cabf8e154c93972d3c65d05c7c3e930128'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"unique-distinct-scope-a","status":"ok","value":{"customerProfileId":"66e9eef7-cf62-5a62-81bd-74fd9102e142","userId":"a638826a-3297-5c97-8ece-6fbf7add9e60","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"0bcce007-bdbc-5d6c-bbd8-9a692a952fb6","semanticKey":"customer-controls-shared-identical-text-key","fingerprint":"fc74b43b2249294f3e78d89fb97f37cabf8e154c93972d3c65d05c7c3e930128","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='bddbc707-3b28-51f7-9cdf-4f845c56d274' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='bb1e784d-4e99-5d6f-b0c5-369f215c0106' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"66e9eef7-cf62-5a62-81bd-74fd9102e142"},"prior":null,"committed":{"id":"66e9eef7-cf62-5a62-81bd-74fd9102e142","userId":"a638826a-3297-5c97-8ece-6fbf7add9e60","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='66e9eef7-cf62-5a62-81bd-74fd9102e142' AND c.user_id='a638826a-3297-5c97-8ece-6fbf7add9e60' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
  AND q.mutation_transaction_id=c.mutation_transaction_id AND h.mutation_transaction_id=c.mutation_transaction_id AND e.mutation_transaction_id=c.mutation_transaction_id
  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='unique-distinct-scope-a' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='07c0bbe9-948f-5bdd-9eaa-392932fc7af5' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"66e9eef7-cf62-5a62-81bd-74fd9102e142","userId":"a638826a-3297-5c97-8ece-6fbf7add9e60","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='25e99801-cb7f-55d7-95b6-41adb2d7c270' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"a638826a-3297-5c97-8ece-6fbf7add9e60","track":"customer","customerProfileId":"66e9eef7-cf62-5a62-81bd-74fd9102e142","sourceCreationRevision":"0","sourceCreationReceipt":"0bcce007-bdbc-5d6c-bbd8-9a692a952fb6","semanticKey":"customer_buyer_profile/66e9eef7-cf62-5a62-81bd-74fd9102e142/default-free-enrollment/v1"}'::jsonb)))=2));
